enum class State {
    DESTROYED, INITIALIZED, CREATED, STARTED, RESUMED;

    fun isAtLeast(s: State) = this >= s
}

fun main() {
    val s = State.STARTED
    println(listOf(
        s.isAtLeast(State.CREATED),
        s.isAtLeast(State.RESUMED),
        State.DESTROYED.isAtLeast(State.INITIALIZED)
    ))
}

